        "correctAnswer": 1,
        "correctAnswers": [
          1
        ],
        "questionType": "MCQ",
        "natRange": null,
        "explanation": "<p dir=\"ltr\"><span>Inner query : (select avg(salary) from emp) runs on whole of the emp table mentioned hence on all employees.  So, option (B) is correct.</span></p>",
        "tag": "GATE 2021 || CSE || MCQ"
