          "<p dir=\"ltr\"><span>option 3</span></p><img src=\"https://media.geeksforgeeks.org/wp-content/cdn-uploads/20200313120720/c1.png\" alt=\"12\" width=\"598\" height=\"84\" loading=\"auto\">",
          "<p dir=\"ltr\"><span>option 4</span></p><img src=\"https://media.geeksforgeeks.org/wp-content/cdn-uploads/20200313120732/d4.png\" alt=\"12\" width=\"596\" height=\"83\" loading=\"auto\">"
