        "questionType": "MCQ",
        "natRange": null,
        "explanation": "<pre><span>#include &lt; iostream &gt;</span><br><span>int max(int *p, int n)</span><br><span>{</span><br><span>&nbsp;&nbsp;&nbsp; int a=0, b=n-1;</span><br><span>&nbsp;&nbsp;&nbsp; while (a!=b)</span><br><span>&nbsp;&nbsp;&nbsp; {</span><br><span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; if (p[a] &lt;= p[b])</span><br><span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {</span><br><span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; a = a+1;</span><br><span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }</span><br><span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; else</span><br><span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; {</span><br><span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; b = b-1;</span><br><span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; }</span><br><span>&nbsp;&nbsp;&nbsp; }</span><br><span>&nbsp;&nbsp;&nbsp; return p[a];</span><br><span>}</span><br><br><span>int main()</span><br><span>{</span><br><span>&nbsp;&nbsp; int arr[] = {10, 5, 1, 40, 30};</span><br><span>&nbsp;&nbsp; int n = sizeof(arr)/sizeof(arr[0]);</span><br><span>&nbsp;&nbsp; std::cout &lt;&lt; max(arr, 5);</span><br><span>}</span><br></pre>",
