          "<p><span>4 2</span><br><br><span>6 1</span><br><br><span>6 1</span></p>",
          "<p><span>4 2</span><br><br><span>6 2</span><br><br><span>2 0</span></p>",
          "<p><span>4 2</span><br><br><span>4 2</span><br><br><span>2 0</span></p>"
