        "natRange": null,
        "explanation": "<p>[Tex]\\text{1. Natural Join: } \\text{Loan} \\bowtie \\text{Borrower} \\text{ on loan\\_num} \\\\[4pt]\\text{This produces tuples with: } (customer\\_name, loan\\_num, branch\\_name, amount) \\\\[6pt]\\text{2. Project on branch\\_name and customer\\_name:} \\\\\\pi_{\\text{branch\\_name, customer\\_name}}(\\text{Loan} \\bowtie \\text{Borrower}) \\\\[4pt]\\text{Resulting pairs:} \\\\\\begin{cases}(\\text{Banjara Hills}, \\text{Anand}) \\\\(\\text{Banjara Hills}, \\text{Karteek}) \\\\(\\text{Kondapur}, \\text{Karteek}) \\\\(\\text{Kondapur}, \\text{Sunil}) \\\\(\\text{SR Nagar}, \\text{Ankita}) \\\\(\\text{SR Nagar}, \\text{Gopal}) \\\\(\\text{SR Nagar}, \\text{Karteek}) \\\\(\\text{Balanagar}, \\text{Karteek}) \\\\(\\text{Balanagar}, \\text{Sunil})\\end{cases} \\\\[10pt]\\text{3. Division:} \\\\\\pi_{\\text{branch\\_name, customer\\_name}}(\\text{Loan} \\bowtie \\text{Borrower}) \\div \\pi_{\\text{branch\\_name}}(\\text{Loan}) \\\\[4pt]\\text{Branches in Loan: } \\{ \\text{Banjara Hills}, \\text{Kondapur}, \\text{SR Nagar}, \\text{Balanagar} \\} \\\\[6pt]\\text{Find customers who appear with all 4 branches.} \\\\[6pt]\\textbf{Only Karteek appears in all 4 branches.} \\\\[10pt]\\therefore \\text{Final Answer: } \\boxed{1}[/Tex]</p>",
        "tag": "GATE DA || NAT || 2025"
