          "<figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20241231153022206788/Screenshot-2024-12-31-153014.png\" alt=\"Screenshot-2024-12-31-153014\" width=\"313\" height=\"343\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20241231153022206788/Screenshot-2024-12-31-153014.png 313w,https://media.geeksforgeeks.org/wp-content/uploads/20241231153022206788/Screenshot-2024-12-31-153014-100.png 91w,https://media.geeksforgeeks.org/wp-content/uploads/20241231153022206788/Screenshot-2024-12-31-153014-200.png 183w,https://media.geeksforgeeks.org/wp-content/uploads/20241231153022206788/Screenshot-2024-12-31-153014-300.png 274w\" loading=\"auto\"><figcaption> </figcaption></figure><p><br></p>",
          "<figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20241231153050840601/Screenshot-2024-12-31-153044.png\" alt=\"Screenshot-2024-12-31-153044\" width=\"308\" height=\"358\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20241231153050840601/Screenshot-2024-12-31-153044.png 308w,https://media.geeksforgeeks.org/wp-content/uploads/20241231153050840601/Screenshot-2024-12-31-153044-100.png 86w,https://media.geeksforgeeks.org/wp-content/uploads/20241231153050840601/Screenshot-2024-12-31-153044-200.png 172w,https://media.geeksforgeeks.org/wp-content/uploads/20241231153050840601/Screenshot-2024-12-31-153044-300.png 258w\" loading=\"auto\"><figcaption> </figcaption></figure><p><br></p>",
          "<figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20241230121334762863/D-100.png\" alt=\"D\" width=\"100\" height=\"64\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20241230121334762863/D.png 199w,https://media.geeksforgeeks.org/wp-content/uploads/20241230121334762863/D-100.png 100w\" loading=\"auto\"><figcaption> </figcaption></figure><p><br></p>"
