          "<figure class=\"image\"><img alt=\"Screenshot-2025-09-16-115110\" height=\"167\" loading=\"auto\" src=\"https://media.geeksforgeeks.org/wp-content/uploads/20250916115326785799/Screenshot-2025-09-16-115110.png\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20250916115326785799/Screenshot-2025-09-16-115110.png 231w,https://media.geeksforgeeks.org/wp-content/uploads/20250916115326785799/Screenshot-2025-09-16-115110-100.png 100w,https://media.geeksforgeeks.org/wp-content/uploads/20250916115326785799/Screenshot-2025-09-16-115110-200.png 200w\" width=\"231\"/><figcaption> </figcaption></figure>",
