          "<figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20250821171659591278/Screenshot-2025-08-21-171054.png\" alt=\"Screenshot-2025-08-21-171054\" width=\"218\" height=\"150\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20250821171659591278/Screenshot-2025-08-21-171054.png 218w,https://media.geeksforgeeks.org/wp-content/uploads/20250821171659591278/Screenshot-2025-08-21-171054-100.png 100w,https://media.geeksforgeeks.org/wp-content/uploads/20250821171659591278/Screenshot-2025-08-21-171054-200.png 200w\" loading=\"auto\"><figcaption> </figcaption></figure><p><br></p>",
          "<figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20250821171749593680/Screenshot-2025-08-21-171108.png\" alt=\"Screenshot-2025-08-21-171108\" width=\"259\" height=\"149\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20250821171749593680/Screenshot-2025-08-21-171108.png 259w,https://media.geeksforgeeks.org/wp-content/uploads/20250821171749593680/Screenshot-2025-08-21-171108-100.png 100w,https://media.geeksforgeeks.org/wp-content/uploads/20250821171749593680/Screenshot-2025-08-21-171108-200.png 200w\" loading=\"auto\"><figcaption> </figcaption></figure><p><br></p>",
