          "<figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20250826123236487999/Screenshot-2025-08-26-122957.png\" alt=\"Screenshot-2025-08-26-122957\" width=\"294\" height=\"165\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20250826123236487999/Screenshot-2025-08-26-122957.png 294w,https://media.geeksforgeeks.org/wp-content/uploads/20250826123236487999/Screenshot-2025-08-26-122957-100.png 100w,https://media.geeksforgeeks.org/wp-content/uploads/20250826123236487999/Screenshot-2025-08-26-122957-200.png 200w\" loading=\"auto\"><figcaption> </figcaption></figure><p><br></p>",
