          "<p dir=\"ltr\" style=\"text-align: justify;\"><span>5(1 − e</span><sup><span>(−t/5)</span></sup><span>) u(t)</span></p>",
          "<p dir=\"ltr\" style=\"text-align: justify;\"><span>(1/5)(1 − e</span><sup><span>(−5t)</span></sup><span>) u(t)</span></p>",
