"><span>\t\t\t= </span><img src=\"data:image/png;base64,\" width=\"96\" height=\"36\" loading=\"auto\"></p><p dir=\"ltr\" style=\"text-align: justify;\"><span>\t\t\ti(t) = 3C (t – 3)</span><sup><span>2</span></sup></p><p dir=\"ltr\" style=\"text-align: justify;\"><span>\tat t = 0, i = 1</span></p><p dir=\"ltr\" style=\"text-align: justify;\"><span>\t\t\ti(0) = 3C (0 – 3)</span><sup><span>2</span></sup><span> = 1</span></p><p dir=\"ltr\" style=\"text-align: justify;\"><span>\t\t\tC = 1/27</span></p><p dir=\"ltr\" style=\"text-align: justify;\"><span>\tat t = </span><img src=\"data:image/png;base64,\" width=\"109\" height=\"36\" loading=\"auto\"></p><p dir=\"ltr\" style=\"text-align: justify;\"><span>\t\t\ti(t = 1.5) = 3C (1.5 – 3)</span><sup><span>2</span></sup></p><p dir=\"ltr\" style=\"text-align: justify;\"><span>\t\t\t= 3C (1.5)</span><sup><span>2</span></sup></p><p style=\"text-align: justify;\"><span>\t\t\t</span><img src=\"data:image/png;base64,\" width=\"91\" height=\"36\" loading=\"auto\"></p><p style=\"text-align: justify;\"><span>\t\t\t</span><img src=\"data:image/png;base64,\" width=\"60\" height=\"36\" loading=\"auto\"></p><p><br></p>",
