          "<p dir=\"ltr\"><i><em class=\"GFGEditorTheme__textItalic\">1-P, 2-R, 3-Q, 4-S</em></i></p>",
          "<p dir=\"ltr\"><i><em class=\"GFGEditorTheme__textItalic\">1-R, 2-Q, 3-S, 4-P</em></i></p>"
