        "natRange": null,
        "explanation": "<p dir=\"ltr\"><span>(C)</span></p><figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20250920113755620935/Annotation-2025-09-19-230707.png\" alt=\"Annotation-2025-09-19-230707\" width=\"269\" height=\"32\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20250920113755620935/Annotation-2025-09-19-230707.png 269w,https://media.geeksforgeeks.org/wp-content/uploads/20250920113755620935/Annotation-2025-09-19-230707-100.png 100w,https://media.geeksforgeeks.org/wp-content/uploads/20250920113755620935/Annotation-2025-09-19-230707-200.png 200w\" loading=\"auto\"><figcaption> </figcaption></figure><figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20250920113755640221/Annotation-2025-09-19-230738.png\" alt=\"Annotation-2025-09-19-230738\" width=\"316\" height=\"194\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20250920113755640221/Annotation-2025-09-19-230738.png 316w,https://media.geeksforgeeks.org/wp-content/uploads/20250920113755640221/Annotation-2025-09-19-230738-100.png 100w,https://media.geeksforgeeks.org/wp-content/uploads/20250920113755640221/Annotation-2025-09-19-230738-200.png 200w,https://media.geeksforgeeks.org/wp-content/uploads/20250920113755640221/Annotation-2025-09-19-230738-300.png 300w\" loading=\"auto\"><figcaption> </figcaption></figure><p dir=\"ltr\"><br></p>",
