        "explanation": "<p dir=\"ltr\"><span>(D)</span></p><figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20250920161602864711/Annotation-2025-09-20-034530.png\" alt=\"Annotation-2025-09-20-034530\" width=\"127\" height=\"85\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20250920161602864711/Annotation-2025-09-20-034530.png 127w,https://media.geeksforgeeks.org/wp-content/uploads/20250920161602864711/Annotation-2025-09-20-034530-100.png 100w\" loading=\"auto\"><figcaption> </figcaption></figure><figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20250920161602877287/Annotation-2025-09-20-034547.png\" alt=\"Annotation-2025-09-20-034547\" width=\"387\" height=\"437\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20250920161602877287/Annotation-2025-09-20-034547.png 387w,https://media.geeksforgeeks.org/wp-content/uploads/20250920161602877287/Annotation-2025-09-20-034547-100.png 89w,https://media.geeksforgeeks.org/wp-content/uploads/20250920161602877287/Annotation-2025-09-20-034547-200.png 177w,https://media.geeksforgeeks.org/wp-content/uploads/20250920161602877287/Annotation-2025-09-20-034547-300.png 266w\" loading=\"auto\"><figcaption> </figcaption></figure><p dir=\"ltr\"><br></p>",
