        "explanation": "<p dir=\"ltr\"><span>(D)</span></p><figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20251003165853262967/Screenshot-2025-10-03-042925.png\" alt=\"Screenshot-2025-10-03-042925\" width=\"346\" height=\"396\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20251003165853262967/Screenshot-2025-10-03-042925.png 346w,https://media.geeksforgeeks.org/wp-content/uploads/20251003165853262967/Screenshot-2025-10-03-042925-100.png 87w,https://media.geeksforgeeks.org/wp-content/uploads/20251003165853262967/Screenshot-2025-10-03-042925-200.png 175w,https://media.geeksforgeeks.org/wp-content/uploads/20251003165853262967/Screenshot-2025-10-03-042925-300.png 262w\" loading=\"auto\"><figcaption> </figcaption></figure><figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20251003165853374854/Screenshot-2025-10-03-042939.png\" alt=\"Screenshot-2025-10-03-042939\" width=\"288\" height=\"107\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20251003165853374854/Screenshot-2025-10-03-042939.png 288w,https://media.geeksforgeeks.org/wp-content/uploads/20251003165853374854/Screenshot-2025-10-03-042939-100.png 100w,https://media.geeksforgeeks.org/wp-content/uploads/20251003165853374854/Screenshot-2025-10-03-042939-200.png 200w\" loading=\"auto\"><figcaption> </figcaption></figure><p dir=\"ltr\"><br></p>",
