        "explanation": "<p dir=\"ltr\"><span>(B)</span></p><figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20251004142424817444/Screenshot-2025-10-04-015450.png\" alt=\"Screenshot-2025-10-04-015450\" width=\"360\" height=\"487\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20251004142424817444/Screenshot-2025-10-04-015450.png 360w,https://media.geeksforgeeks.org/wp-content/uploads/20251004142424817444/Screenshot-2025-10-04-015450-100.png 74w,https://media.geeksforgeeks.org/wp-content/uploads/20251004142424817444/Screenshot-2025-10-04-015450-200.png 148w,https://media.geeksforgeeks.org/wp-content/uploads/20251004142424817444/Screenshot-2025-10-04-015450-300.png 222w\" loading=\"auto\"><figcaption> </figcaption></figure><figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20251004142425092678/Screenshot-2025-10-04-015509.png\" alt=\"Screenshot-2025-10-04-015509\" width=\"343\" height=\"50\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20251004142425092678/Screenshot-2025-10-04-015509.png 343w,https://media.geeksforgeeks.org/wp-content/uploads/20251004142425092678/Screenshot-2025-10-04-015509-100.png 100w,https://media.geeksforgeeks.org/wp-content/uploads/20251004142425092678/Screenshot-2025-10-04-015509-200.png 200w,https://media.geeksforgeeks.org/wp-content/uploads/20251004142425092678/Screenshot-2025-10-04-015509-300.png 300w\" loading=\"auto\"><figcaption> </figcaption></figure><p dir=\"ltr\"><br></p>",
