        "correctAnswer": 0,
        "correctAnswers": [
          0
        ],
        "questionType": "MCQ",
        "natRange": null,
        "explanation": "<p dir=\"ltr\"><span>(A)</span></p><figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20251004152103681680/Screenshot-2025-10-04-025151.png\" alt=\"Screenshot-2025-10-04-025151\" width=\"275\" height=\"143\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20251004152103681680/Screenshot-2025-10-04-025151.png 275w,https://media.geeksforgeeks.org/wp-content/uploads/20251004152103681680/Screenshot-2025-10-04-025151-100.png 100w,https://media.geeksforgeeks.org/wp-content/uploads/20251004152103681680/Screenshot-2025-10-04-025151-200.png 200w\" loading=\"auto\"><figcaption> </figcaption></figure><p dir=\"ltr\"><br></p>",
        "tag": "GATE 2012 | 2 marks | MCQ"
