          "<figure class=\"image\"><img alt=\"Screenshot-2025-10-08-123009\" height=\"41\" loading=\"auto\" src=\"https://media.geeksforgeeks.org/wp-content/uploads/20251008123416524243/Screenshot-2025-10-08-123009.png\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20251008123416524243/Screenshot-2025-10-08-123009.png 342w,https://media.geeksforgeeks.org/wp-content/uploads/20251008123416524243/Screenshot-2025-10-08-123009-100.png 100w,https://media.geeksforgeeks.org/wp-content/uploads/20251008123416524243/Screenshot-2025-10-08-123009-200.png 200w,https://media.geeksforgeeks.org/wp-content/uploads/20251008123416524243/Screenshot-2025-10-08-123009-300.png 300w\" width=\"342\"/><figcaption> </figcaption></figure>",
