        "explanation": "<p dir=\"ltr\"><span>(C)</span></p><figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20250922113321071994/Annotation-2025-09-21-230345.png\" alt=\"Annotation-2025-09-21-230345\" width=\"386\" height=\"455\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20250922113321071994/Annotation-2025-09-21-230345.png 386w,https://media.geeksforgeeks.org/wp-content/uploads/20250922113321071994/Annotation-2025-09-21-230345-100.png 85w,https://media.geeksforgeeks.org/wp-content/uploads/20250922113321071994/Annotation-2025-09-21-230345-200.png 170w,https://media.geeksforgeeks.org/wp-content/uploads/20250922113321071994/Annotation-2025-09-21-230345-300.png 255w\" loading=\"auto\"><figcaption> </figcaption></figure><figure class=\"image\"><img src=\"https://media.geeksforgeeks.org/wp-content/uploads/20250922113321211530/Annotation-2025-09-21-230359.png\" alt=\"Annotation-2025-09-21-230359\" width=\"360\" height=\"370\" srcset=\"https://media.geeksforgeeks.org/wp-content/uploads/20250922113321211530/Annotation-2025-09-21-230359.png 360w,https://media.geeksforgeeks.org/wp-content/uploads/20250922113321211530/Annotation-2025-09-21-230359-100.png 97w,https://media.geeksforgeeks.org/wp-content/uploads/20250922113321211530/Annotation-2025-09-21-230359-200.png 195w,https://media.geeksforgeeks.org/wp-content/uploads/20250922113321211530/Annotation-2025-09-21-230359-300.png 292w\" loading=\"auto\"><figcaption> </figcaption></figure><p dir=\"ltr\"><br></p>",
